<?php\n\nuse App\Models\Company;\nuse App\Models\Section;\nuse App\Models\Product;\nuse App\Models\User;\nuse App\Models\VatRate;\nuse Illuminate\Foundation\Testing\RefreshDatabase;\n\nuses(RefreshDatabase::class);\n\ntest('vismass sales transaction includes vat calculations', function () {\n    // Setup VISMASS company and VAT\n    $company = Company::factory()->create(['company_code' => 'VIS001']);\n    $user = User::factory()->create(['company_code' => 'VIS001']);\n    $section = Section::factory()->create([\n        'company_code' => 'VIS001',\n        'is_main_stock' => true\n    ]);\n    \n    $vatRate = VatRate::factory()->create([\n        'company_id' => $company->id,\n        'vat_rate' => 15.00,\n        'is_active' => true\n    ]);\n    \n    $product = Product::factory()->create([\n        'company_code' => 'VIS001',\n        'section_code' => $section->section_code,\n        'VATItem' => true,\n        'SlsPri' => 100.00\n    ]);\n    \n    $this->actingAs($user);\n    \n    $response = $this->postJson('/vismass/sales', [\n        'customer_name' => 'Test Customer',\n        'items' => [\n            [\n                'product_id' => $product->ItmKy,\n                'batch_no' => 'DEFAULT',\n                'quantity' => 2,\n                'unit_price' => 100.00,\n                'vat_inclusive' => false\n            ]\n        ],\n        'payment_method' => 'cash',\n        'total_amount' => 200.00,\n        'vat_amount' => 30.00,\n        'grand_total' => 230.00\n    ]);\n    \n    $response->assertStatus(201);\n    $response->assertJsonStructure([\n        'data' => [\n            'id',\n            'transaction_number',\n            'total_amount',\n            'vat_amount',\n            'grand_total',\n            'vat_rate'\n        ]\n    ]);\n    \n    expect($response->json('data.vat_amount'))->toBe(30.00);\n    expect($response->json('data.vat_rate'))->toBe(15.00);\n});\n\ntest('vismass purchase includes batch management', function () {\n    $company = Company::factory()->create(['company_code' => 'VIS001']);\n    $user = User::factory()->create(['company_code' => 'VIS001']);\n    $section = Section::factory()->create([\n        'company_code' => 'VIS001',\n        'is_main_stock' => true\n    ]);\n    \n    $this->actingAs($user);\n    \n    $response = $this->postJson('/vismass/purchases', [\n        'supplier_code' => 'SUP001',\n        'section_code' => $section->section_code,\n        'items' => [\n            [\n                'item_code' => 'ITEM001',\n                'item_name' => 'Test Item',\n                'batch_no' => 'BATCH001',\n                'quantity' => 10,\n                'cost_price' => 50.00,\n                'selling_price' => 75.00\n            ]\n        ],\n        'total_amount' => 500.00\n    ]);\n    \n    $response->assertStatus(201);\n    \n    // Verify batch was created\n    $this->assertDatabaseHas('itemmaster', [\n        'ItemCode' => 'ITEM001',\n        'batch_no' => 'BATCH001',\n        'company_code' => 'VIS001',\n        'section_code' => $section->section_code\n    ]);\n});\n\ntest('vismass service job creation with customer management', function () {\n    $company = Company::factory()->create(['company_code' => 'VIS001']);\n    $user = User::factory()->create(['company_code' => 'VIS001']);\n    $section = Section::factory()->create([\n        'company_code' => 'VIS001',\n        'is_main_stock' => true\n    ]);\n    \n    $this->actingAs($user);\n    \n    $response = $this->postJson('/vismass/services', [\n        'customer_name' => 'John Doe',\n        'customer_phone' => '0771234567',\n        'device_name' => 'iPhone 12',\n        'device_brand' => 'Apple',\n        'serial_number' => 'ABC123456',\n        'issue_description' => 'Screen cracked',\n        'service_charge' => 5000.00,\n        'advance_payment' => 2000.00\n    ]);\n    \n    $response->assertStatus(201);\n    $response->assertJsonStructure([\n        'data' => [\n            'id',\n            'job_number',\n            'customer_name',\n            'device_name',\n            'service_charge',\n            'status'\n        ]\n    ]);\n});\n\ntest('vismass stock transfer between main stock sections', function () {\n    $company = Company::factory()->create(['company_code' => 'VIS001']);\n    $user = User::factory()->create(['company_code' => 'VIS001']);\n    \n    $sourceSection = Section::factory()->create([\n        'company_code' => 'VIS001',\n        'section_code' => 'MAIN001',\n        'is_main_stock' => true\n    ]);\n    \n    $targetSection = Section::factory()->create([\n        'company_code' => 'VIS001',\n        'section_code' => 'MAIN002',\n        'is_main_stock' => true\n    ]);\n    \n    $product = Product::factory()->create([\n        'company_code' => 'VIS001',\n        'section_code' => $sourceSection->section_code,\n        'batch_no' => 'BATCH001'\n    ]);\n    \n    $this->actingAs($user);\n    \n    $response = $this->postJson('/vismass/stock/transfers', [\n        'from_section_code' => $sourceSection->section_code,\n        'to_section_code' => $targetSection->section_code,\n        'items' => [\n            [\n                'product_id' => $product->ItmKy,\n                'batch_no' => 'BATCH001',\n                'quantity' => 5,\n                'transfer_type' => 'stock_movement'\n            ]\n        ],\n        'notes' => 'Stock redistribution'\n    ]);\n    \n    $response->assertStatus(201);\n    \n    // Verify transfer record created\n    $this->assertDatabaseHas('stock_transfers', [\n        'from_section_code' => $sourceSection->section_code,\n        'to_section_code' => $targetSection->section_code,\n        'status' => 'completed'\n    ]);\n});\n\ntest('vismass vat rate management', function () {\n    $company = Company::factory()->create(['company_code' => 'VIS001']);\n    $user = User::factory()->create(['company_code' => 'VIS001']);\n    \n    $this->actingAs($user);\n    \n    // Create VAT rate\n    $response = $this->postJson('/vismass/vat/rates', [\n        'vat_rate' => 18.00,\n        'vat_no' => 'VAT123456789',\n        'effective_date' => now()->format('Y-m-d'),\n        'is_active' => true\n    ]);\n    \n    $response->assertStatus(201);\n    \n    // Verify VAT rate created\n    $this->assertDatabaseHas('vat_rates', [\n        'company_id' => $company->id,\n        'vat_rate' => 18.00,\n        'vat_no' => 'VAT123456789',\n        'is_active' => true\n    ]);\n});\n\ntest('vismass category management for products', function () {\n    $company = Company::factory()->create(['company_code' => 'VIS001']);\n    $user = User::factory()->create(['company_code' => 'VIS001']);\n    \n    $this->actingAs($user);\n    \n    $response = $this->postJson('/vismass/admin/categories', [\n        'conkey' => 'CAT',\n        'concode' => 'ELECTRONICS',\n        'cname' => 'Electronics',\n        'description' => 'Electronic items and accessories',\n        'company_code' => 'VIS001',\n        'is_active' => true\n    ]);\n    \n    $response->assertStatus(201);\n    \n    // Verify category created\n    $this->assertDatabaseHas('code_masters', [\n        'conkey' => 'CAT',\n        'concode' => 'ELECTRONICS',\n        'cname' => 'Electronics',\n        'company_code' => 'VIS001'\n    ]);\n});